// Exact type contracts per specification

export type TaskStatus = "todo" | "in-progress" | "done";

export interface User {
  id: string;
  name: string;
  email: string;
}

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO 8601
}

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO 8601
}

// Event Bus Contract
export interface IEventBus {
  publish(event: string, payload: unknown): void;
  subscribe(event: string, callback: (payload: unknown) => void): void;
}

export interface TaskAssignedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string;
}

export interface TaskStatusChangedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string | null;
  oldStatus: TaskStatus;
  newStatus: TaskStatus;
}

export interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  authorName: string;
}

// Service Contracts
export interface IUserService {
  create(input: { name: string; email: string }): User;
  getById(id: string): User;
  getAll(): User[];
  update(id: string, input: Partial<{ name: string; email: string }>): User;
  delete(id: string): void;
}

export interface IProjectService {
  create(input: { name: string; description: string }): Project;
  getById(id: string): Project;
  getAll(): Project[];
  update(id: string, input: Partial<{ name: string; description: string }>): Project;
  delete(id: string): void;
  addMember(projectId: string, userId: string): Project;
  removeMember(projectId: string, userId: string): Project;
}

export interface ITaskService {
  create(input: { title: string; description: string; projectId: string }): Task;
  getById(id: string): Task;
  getByProject(projectId: string): Task[];
  update(id: string, input: Partial<{ title: string; description: string }>): Task;
  delete(id: string): void;
  assign(taskId: string, assigneeId: string): Task;
  changeStatus(taskId: string, newStatus: TaskStatus): Task;
}

export interface ICommentService {
  create(input: { taskId: string; authorId: string; body: string }): Comment;
  getById(id: string): Comment;
  getByTask(taskId: string): Comment[];
  delete(id: string): void;
}

export interface INotificationService {
  getByUser(userId: string): Notification[];
  markAsRead(notificationId: string): Notification;
}

import { EventEmitter } from "events";
import { IEventBus } from "./types";

export class EventBus implements IEventBus {
  private emitter = new EventEmitter();

  publish(event: string, payload: unknown): void {
    this.emitter.emit(event, payload);
  }

  subscribe(event: string, callback: (payload: unknown) => void): void {
    this.emitter.on(event, callback);
  }
}

import { User, IUserService } from "../types";
import { randomUUID } from "crypto";

export class UserService implements IUserService {
  // RULE 2: Exclusive data ownership - private Map
  private users: Map<string, User> = new Map();

  create(input: { name: string; email: string }): User {
    const id = randomUUID();
    const user: User = { id, name: input.name, email: input.email };
    this.users.set(id, user);
    return user;
  }

  getById(id: string): User {
    const u = this.users.get(id);
    if (!u) throw new Error("User not found");
    return u;
  }

  getAll(): User[] {
    return Array.from(this.users.values());
  }

  update(id: string, input: Partial<{ name: string; email: string }>): User {
    const u = this.getById(id);
    const updated: User = { ...u, ...input };
    this.users.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    if (!this.users.delete(id)) throw new Error("User not found");
  }
}

import { Project, IProjectService } from "../types";
import { randomUUID } from "crypto";

export class ProjectService implements IProjectService {
  private projects: Map<string, Project> = new Map();

  create(input: { name: string; description: string }): Project {
    const id = randomUUID();
    const project: Project = { id, name: input.name, description: input.description, memberIds: [] };
    this.projects.set(id, project);
    return project;
  }

  getById(id: string): Project {
    const p = this.projects.get(id);
    if (!p) throw new Error("Project not found");
    return p;
  }

  getAll(): Project[] {
    return Array.from(this.projects.values());
  }

  update(id: string, input: Partial<{ name: string; description: string }>): Project {
    const p = this.getById(id);
    const updated: Project = { ...p, ...input } as Project;
    this.projects.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    if (!this.projects.delete(id)) throw new Error("Project not found");
  }

  addMember(projectId: string, userId: string): Project {
    const p = this.getById(projectId);
    if (!p.memberIds.includes(userId)) {
      p.memberIds = [...p.memberIds, userId];
      this.projects.set(projectId, p);
    }
    return p;
  }

  removeMember(projectId: string, userId: string): Project {
    const p = this.getById(projectId);
    p.memberIds = p.memberIds.filter((id) => id !== userId);
    this.projects.set(projectId, p);
    return p;
  }
}

import { Task, ITaskService, TaskStatus, TaskAssignedPayload, TaskStatusChangedPayload } from "../types";
import { randomUUID } from "crypto";
import { IEventBus } from "../types";

export class TaskService implements ITaskService {
  private tasks: Map<string, Task> = new Map();
  private eventBus: IEventBus;

  constructor(eventBus: IEventBus) {
    this.eventBus = eventBus;
  }

  create(input: { title: string; description: string; projectId: string }): Task {
    const id = randomUUID();
    const task: Task = { id, title: input.title, description: input.description, status: "todo", assigneeId: null, projectId: input.projectId };
    this.tasks.set(id, task);
    return task;
  }

  getById(id: string): Task {
    const t = this.tasks.get(id);
    if (!t) throw new Error("Task not found");
    return t;
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter((t) => t.projectId === projectId);
  }

  update(id: string, input: Partial<{ title: string; description: string }>): Task {
    const t = this.getById(id);
    const updated: Task = { ...t, ...input } as Task;
    this.tasks.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    if (!this.tasks.delete(id)) throw new Error("Task not found");
  }

  assign(taskId: string, assigneeId: string): Task {
    const t = this.getById(taskId);
    t.assigneeId = assigneeId;
    this.tasks.set(taskId, t);
    const payload: TaskAssignedPayload = { taskId: t.id, taskTitle: t.title, assigneeId };
    this.eventBus.publish("task.assigned", payload);
    return t;
  }

  changeStatus(taskId: string, newStatus: TaskStatus): Task {
    const t = this.getById(taskId);
    const order: TaskStatus[] = ["todo", "in-progress", "done"];
    const oldIndex = order.indexOf(t.status);
    const newIndex = order.indexOf(newStatus);
    if (newIndex === -1) throw new Error("Invalid status");
    // enforce forward-only and no skipping
    if (newIndex <= oldIndex) throw new Error("Invalid status transition: must move forward");
    if (newIndex - oldIndex !== 1) throw new Error("Invalid status transition: cannot skip states");

    const oldStatus = t.status;
    t.status = newStatus;
    this.tasks.set(taskId, t);

    const payload: TaskStatusChangedPayload = { taskId: t.id, taskTitle: t.title, assigneeId: t.assigneeId, oldStatus, newStatus };
    this.eventBus.publish("task.statusChanged", payload);
    return t;
  }
}

import { Comment, ICommentService, CommentAddedPayload } from "../types";
import { randomUUID } from "crypto";
import { IEventBus } from "../types";

export class CommentService implements ICommentService {
  private comments: Map<string, Comment> = new Map();
  private eventBus: IEventBus;

  constructor(eventBus: IEventBus) {
    this.eventBus = eventBus;
  }

  create(input: { taskId: string; authorId: string; body: string }): Comment {
    const id = randomUUID();
    const createdAt = new Date().toISOString();
    const comment: Comment = { id, taskId: input.taskId, authorId: input.authorId, body: input.body, createdAt };
    this.comments.set(id, comment);

    // publish event - but we need task title and author name. The spec's payload includes taskTitle and authorName.
    // Services cannot reach into TaskService or UserService; router/main will provide authorName and taskTitle by letting caller include them? 
    // However spec expects CommentService to publish CommentAddedPayload with authorName and taskTitle. To comply while honoring RULE 1, we'll include only known fields and main will subscribe to comment creation and republish enriched event.

    // But spec explicitly: CommentService publishes "comment.added" → CommentAddedPayload
    // To comply without cross-service imports, we will require caller (router) to provide authorName and taskTitle in input (not ideal). Alternatively, CommentService can publish minimal payload and main can translate. But spec requires CommentService publishes CommentAddedPayload. We'll include placeholder empty strings; main will ignore and use stored comment to create proper notifications. Simpler: include authorName and taskTitle as empty; main will listen to "comment.added" and look up data via services. That's allowed.

    const payload: CommentAddedPayload = { commentId: id, taskId: input.taskId, taskTitle: "", authorId: input.authorId, authorName: "" };
    this.eventBus.publish("comment.added", payload);

    return comment;
  }

  getById(id: string): Comment {
    const c = this.comments.get(id);
    if (!c) throw new Error("Comment not found");
    return c;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.comments.values()).filter((c) => c.taskId === taskId);
  }

  delete(id: string): void {
    if (!this.comments.delete(id)) throw new Error("Comment not found");
  }
}

import { Notification, INotificationService } from "../types";
import { randomUUID } from "crypto";

export class NotificationService implements INotificationService {
  private notifications: Map<string, Notification> = new Map();

  // helper method used by main to create notifications in response to events
  createNotification(userId: string, message: string): Notification {
    const id = randomUUID();
    const createdAt = new Date().toISOString();
    const n: Notification = { id, userId, message, read: false, createdAt };
    this.notifications.set(id, n);
    return n;
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.notifications.values()).filter((n) => n.userId === userId);
  }

  markAsRead(notificationId: string): Notification {
    const n = this.notifications.get(notificationId);
    if (!n) throw new Error("Notification not found");
    const updated = { ...n, read: true };
    this.notifications.set(notificationId, updated);
    return updated;
  }
}

import { createServer, IncomingMessage, ServerResponse } from "http";
import { parse as parseUrl } from "url";
import { UserService } from "./services/user-service";
import { ProjectService } from "./services/project-service";
import { TaskService } from "./services/task-service";
import { CommentService } from "./services/comment-service";
import { NotificationService } from "./services/notification-service";
import { EventBus } from "./event-bus";
import { IEventBus } from "./types";

function jsonResponse(res: ServerResponse, status: number, data: unknown) {
  const body = JSON.stringify(data);
  res.writeHead(status, { "Content-Type": "application/json" });
  res.end(body);
}

async function readJson(req: IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on("data", (chunk) => chunks.push(Buffer.from(chunk)));
    req.on("end", () => {
      if (chunks.length === 0) return resolve({});
      try {
        const str = Buffer.concat(chunks).toString();
        resolve(JSON.parse(str));
      } catch (e) {
        reject(e);
      }
    });
    req.on("error", reject);
  });
}

export function createRouter() {
  const eventBus: IEventBus = new EventBus();
  const userService = new UserService();
  const projectService = new ProjectService();
  const taskService = new TaskService(eventBus);
  const commentService = new CommentService(eventBus);
  const notificationService = new NotificationService();

  // Wire events: main() will rewire in main.ts, but router also can be used standalone. For simplicity, expose services and eventBus via closure return.

  const server = createServer(async (req: IncomingMessage, res: ServerResponse) => {
    try {
      const url = parseUrl(req.url || "", true);
      const method = req.method || "GET";
      const path = url.pathname || "/";

      // Routing
      if (method === "GET" && path === "/users") {
        return jsonResponse(res, 200, userService.getAll());
      }
      if (method === "POST" && path === "/users") {
        const body = await readJson(req);
        const u = userService.create(body);
        return jsonResponse(res, 201, u);
      }
      if (method === "GET" && path?.startsWith("/users/")) {
        const id = path.split("/")[2];
        return jsonResponse(res, 200, userService.getById(id));
      }
      if (method === "PUT" && path?.startsWith("/users/")) {
        const id = path.split("/")[2];
        const body = await readJson(req);
        return jsonResponse(res, 200, userService.update(id, body));
      }
      if (method === "DELETE" && path?.startsWith("/users/")) {
        const id = path.split("/")[2];
        userService.delete(id);
        return jsonResponse(res, 204, null);
      }

      // Projects
      if (method === "GET" && path === "/projects") {
        return jsonResponse(res, 200, projectService.getAll());
      }
      if (method === "POST" && path === "/projects") {
        const body = await readJson(req);
        const p = projectService.create(body);
        return jsonResponse(res, 201, p);
      }
      if (method === "GET" && path?.startsWith("/projects/")) {
        const id = path.split("/")[2];
        return jsonResponse(res, 200, projectService.getById(id));
      }
      if (method === "PUT" && path?.startsWith("/projects/")) {
        const id = path.split("/")[2];
        const body = await readJson(req);
        return jsonResponse(res, 200, projectService.update(id, body));
      }
      if (method === "DELETE" && path?.startsWith("/projects/")) {
        const id = path.split("/")[2];
        projectService.delete(id);
        return jsonResponse(res, 204, null);
      }
      if (method === "POST" && path?.endsWith("/members")) {
        const id = path.split("/")[2];
        const body = await readJson(req);
        const p = projectService.addMember(id, body.userId);
        return jsonResponse(res, 200, p);
      }
      if (method === "DELETE" && path?.endsWith("/members")) {
        const id = path.split("/")[2];
        const body = await readJson(req);
        const p = projectService.removeMember(id, body.userId);
        return jsonResponse(res, 200, p);
      }

      // Tasks
      if (method === "GET" && path === "/tasks") {
        const projectId = url.query.projectId as string | undefined;
        if (!projectId) return jsonResponse(res, 400, { error: "projectId required" });
        return jsonResponse(res, 200, taskService.getByProject(projectId));
      }
      if (method === "POST" && path === "/tasks") {
        const body = await readJson(req);
        const t = taskService.create(body);
        return jsonResponse(res, 201, t);
      }
      if (method === "GET" && path?.startsWith("/tasks/")) {
        const id = path.split("/")[2];
        return jsonResponse(res, 200, taskService.getById(id));
      }
      if (method === "PUT" && /^\/tasks\/[^/]+$/.test(path || "")) {
        const id = path.split("/")[2];
        const body = await readJson(req);
        return jsonResponse(res, 200, taskService.update(id, body));
      }
      if (method === "DELETE" && path?.startsWith("/tasks/")) {
        const id = path.split("/")[2];
        taskService.delete(id);
        return jsonResponse(res, 204, null);
      }
      if (method === "PUT" && path?.endsWith("/status")) {
        const id = path.split("/")[2];
        const body = await readJson(req);
        const t = taskService.changeStatus(id, body.status);
        return jsonResponse(res, 200, t);
      }
      if (method === "PUT" && path?.endsWith("/assign")) {
        const id = path.split("/")[2];
        const body = await readJson(req);
        const t = taskService.assign(id, body.assigneeId);
        return jsonResponse(res, 200, t);
      }

      // Comments
      if (method === "GET" && path === "/comments") {
        const taskId = url.query.taskId as string | undefined;
        if (!taskId) return jsonResponse(res, 400, { error: "taskId required" });
        return jsonResponse(res, 200, commentService.getByTask(taskId));
      }
      if (method === "POST" && path === "/comments") {
        const body = await readJson(req);
        const c = commentService.create(body);
        return jsonResponse(res, 201, c);
      }
      if (method === "GET" && path?.startsWith("/comments/")) {
        const id = path.split("/")[2];
        return jsonResponse(res, 200, commentService.getById(id));
      }
      if (method === "DELETE" && path?.startsWith("/comments/")) {
        const id = path.split("/")[2];
        commentService.delete(id);
        return jsonResponse(res, 204, null);
      }

      // Notifications
      if (method === "GET" && path === "/notifications") {
        const userId = url.query.userId as string | undefined;
        if (!userId) return jsonResponse(res, 400, { error: "userId required" });
        return jsonResponse(res, 200, notificationService.getByUser(userId));
      }
      if (method === "PUT" && path?.endsWith("/read")) {
        const id = path.split("/")[2];
        const n = notificationService.markAsRead(id);
        return jsonResponse(res, 200, n);
      }

      jsonResponse(res, 404, { error: "Not found" });
    } catch (e: any) {
      jsonResponse(res, 500, { error: e.message || String(e) });
    }
  });

  return { server, services: { userService, projectService, taskService, commentService, notificationService }, eventBus };
}

import { createRouter } from "./router";
import { EventBus } from "./event-bus";
import { TaskAssignedPayload, TaskStatusChangedPayload, CommentAddedPayload } from "./types";

(async function main() {
  const { server, services, eventBus } = createRouter();
  const { userService, projectService, taskService, commentService, notificationService } = services;

  // Wire event handlers per spec
  // task.assigned -> notification
  eventBus.subscribe("task.assigned", (payload) => {
    const p = payload as TaskAssignedPayload;
    // create notification for assignee
    const message = `Task '${p.taskTitle}' assigned to you`;
    notificationService.createNotification(p.assigneeId, message);
  });

  eventBus.subscribe("task.statusChanged", (payload) => {
    const p = payload as TaskStatusChangedPayload;
    const message = `Task '${p.taskTitle}' status changed to ${p.newStatus}`;
    if (p.assigneeId) notificationService.createNotification(p.assigneeId, message);
  });

  // comment.added -> create notification for task assignee about new comment
  eventBus.subscribe("comment.added", (payload) => {
    const p = payload as CommentAddedPayload;
    // Need to look up task to find assignee and task title
    try {
      const task = taskService.getById(p.taskId);
      const author = userService.getById(p.authorId);
      const message = `New comment on '${task.title}' by ${author.name}`;
      if (task.assigneeId) notificationService.createNotification(task.assigneeId, message);
    } catch (e) {
      // ignore
    }
  });

  const port = process.env.PORT ? Number(process.env.PORT) : 3000;
  server.listen(port, () => {
    console.log(`Server listening on http://localhost:${port}`);
  });
})();

import { createRouter } from "./router";
import { request as httpRequest } from "http";

function req(method: string, path: string, body?: any): Promise<{ status: number; body: any }> {
  return new Promise((resolve, reject) => {
    const opts = { hostname: "localhost", port: 3000, path, method, headers: { "Content-Type": "application/json" } } as any;
    const r = httpRequest(opts, (res) => {
      const chunks: Buffer[] = [];
      res.on("data", (c) => chunks.push(Buffer.from(c)));
      res.on("end", () => {
        const str = Buffer.concat(chunks).toString();
        const parsed = str ? JSON.parse(str) : null;
        resolve({ status: res.statusCode || 0, body: parsed });
      });
    });
    r.on("error", reject);
    if (body) r.write(JSON.stringify(body));
    r.end();
  });
}

async function runDemo() {
  const { server } = createRouter();
  server.listen(3000);
  // create users
  const u1 = await req("POST", "/users", { name: "Alice", email: "alice@example.com" });
  const u2 = await req("POST", "/users", { name: "Bob", email: "bob@example.com" });
